  // Where the matrix's top-left corner sits at spawn, so the piece's top row is board row 0.
  var SPAWN = {
    I: [-1, 3], O: [0, 4], T: [0, 3], S: [0, 3], Z: [0, 3], J: [0, 3], L: [0, 3]
  };
  // Points for clearing 1-4 rows at once, multiplied by the current level. Clearing rows
  // together must always pay more than clearing the same rows one at a time; otherwise there
  // is no reason to build a stack.
  var LINE_SCORES = [0, 100, 300, 500, 800];
  var SOFT_DROP_POINTS = 1; // per cell moved down by the player
  var HARD_DROP_POINTS = 2; // per cell dropped
  // Locking rule: a gravity step that cannot move the piece down counts one tick of lock
  // delay; the piece locks on the LOCK_DELAY-th such tick. Moving left/right while resting
  // restarts the delay, at most MAX_LOCK_RESETS times per piece. Hard drop locks at once.
  var LOCK_DELAY = 2;
  var MAX_LOCK_RESETS = 3;

  // Offsets for each rotation state: ROTATIONS[type][rot] = [[r, c], ...]
  var ROTATIONS = {};
    fillUpcoming();
