    if (!fits(p, p.rot, p.row, p.col)) {
      current = null;
      status = "gameover";
      stopTimer();
      return;
    }
    current = p;
  }

  function tryMove(dr, dc) {
    if (!current) return false;
    if (!fits(current, current.rot, current.row + dr, current.col + dc)) return false;
    current.row += dr;
    current.col += dc;
    if (dr > 0) current.lockTicks = 0;
    return true;
  }

  function isResting() {
    return !fits(current, current.rot, current.row + 1, current.col);
  }

  // Sideways move. If the piece was resting, this restarts its lock delay (capped per piece).
  function tryShift(dc) {
    if (!current) return false;
    var resting = isResting();
    if (!tryMove(0, dc)) return false;
    if (resting && current.lockResets < MAX_LOCK_RESETS) {
      current.lockResets++;
      current.lockTicks = 0;
    }
    return true;
  }

  // Clockwise rotation. If the rotated shape does not fit in place, try sideways shifts only
  // (a vertical kick would let a resting piece climb and stay in the air). If nothing fits,
  // the piece is left untouched.
  function tryRotateCW() {
    if (!current) return false;
    var rot = (current.rot + 1) % 4;
    var kicks = [0, -1, 1, -2, 2];
    for (var i = 0; i < kicks.length; i++) {
      var col = current.col + kicks[i];
      if (fits(current, rot, current.row, col)) {
        current.rot = rot;
        current.col = col;
        return true;
      }
    }
    return false;
  }

  function clearLines() {
    var kept = board.filter(function (row) {
      return row.some(function (cell) { return !cell; });
    });
    var cleared = ROWS - kept.length;
    if (cleared === 0) return;
    while (kept.length < ROWS) {
      var row = [];
      for (var c = 0; c < COLS; c++) row.push(null);
      kept.unshift(row);
    }
    board = kept;
    score += LINE_SCORES[cleared] * level;
    lines += cleared;
    var newLevel = Math.floor(lines / 10) + 1;
    if (newLevel !== level) {
      level = newLevel;
      if (timer !== null) startTimer();
    }
  }

  function lockPiece() {
    pieceCells(current, current.rot, current.row, current.col).forEach(function (rc) {
      board[rc[0]][rc[1]] = current.type;
    });
    current = null;
    clearLines();
    spawn();
  }

  // One gravity step. The real timer and __tetris.tick both run this.
  function gravityStep() {
    if (status !== "running" || !current) return;
    if (tryMove(1, 0)) return;
    current.lockTicks++;
    if (current.lockTicks >= LOCK_DELAY) lockPiece();
  }

  function performAction(action) {
    if (status !== "running" || !current) return;
    switch (action) {
      case "left": tryShift(-1); break;
      case "right": tryShift(1); break;
      case "softDrop":
