      performAction(action);
      render();
    },
    getBoard: function () {
      return board.map(function (row) {
        return row.map(function (cell) { return cell || "."; }).join("");
      });
    },
    getState: function () {
      return {
        current: current
          ? { type: current.type, cells: pieceCells(current, current.rot, current.row, current.col) }
          : null,
        next: upcoming.slice(),
