    x: "rotateCW",
    X: "rotateCW",
    " ": "hardDrop"
  };

  document.addEventListener("keydown", function (e) {
    var action = KEYS[e.key];
    if (!action) return;
    e.preventDefault();
    window.__tetris.input(action);
  });

  document.getElementById("newGame").addEventListener("click", function (e) {
    e.currentTarget.blur();
    window.__tetris.newGame();
  });

  window.__tetris.newGame();
})();
