    if (status === "running") startTimer();
  }

  // ---- Rendering (synchronous) ----
  var boardEl = document.getElementById("board");
  var overlayEl = document.getElementById("overlay");
  var scoreEl = document.getElementById("score");
  var levelEl = document.getElementById("level");
  var linesEl = document.getElementById("lines");
  var previewEl = document.getElementById("preview");
  var cellEls = [];
  var previewItems = []; // { el, cells: [8 divs] }, soonest first

  (function buildDom() {
    for (var r = 0; r < ROWS; r++) {
      cellEls.push([]);
      for (var c = 0; c < COLS; c++) {
        var el = document.createElement("div");
        el.className = "cell";
        el.setAttribute("data-testid", "cell");
        el.setAttribute("data-row", String(r));
        el.setAttribute("data-col", String(c));
        el.setAttribute("data-filled", "false");
        el.setAttribute("data-piece", "");
        boardEl.insertBefore(el, overlayEl);
        cellEls[r].push(el);
      }
    }
    for (var i = 0; i < PREVIEW_COUNT; i++) {
      var item = document.createElement("div");
      item.className = "preview-item";
      item.setAttribute("data-testid", "next-piece-item");
      var cells = [];
      for (var k = 0; k < 8; k++) {
        var cell = document.createElement("div");
        item.appendChild(cell);
        cells.push(cell);
      }
      previewEl.appendChild(item);
      previewItems.push({ el: item, cells: cells });
    }
