  function paint(el, type) {
    var cls = el.className.replace(/\s*p-[IOTSZJL]\b/g, "");
    el.className = type ? cls + " p-" + type : cls;
  }

  function render() {
    var drawn = board.map(function (row) { return row.slice(); });
